"using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

// ============================================================================
// 1. ANA ÇEKİCİ FİZİK KONTROLCÜSÜ
// ============================================================================
[DisallowMultipleComponent]
[RequireComponent(typeof(Rigidbody))]
public class MobileTruckCompleteSystem : MonoBehaviour
{
    [Header(\"Tekerlekler (Opsiyonel - Boşsa Sadece Rigidbody İle Çalışır)\")]
    [SerializeField] private WheelCollider[] steerWheels;
    [SerializeField] private WheelCollider[] driveWheels;
    [SerializeField] private WheelCollider[] allWheels;

    [Header(\"Motor ve Fren Ayarları\")]
    [SerializeField] private float maxMotorTorque = 2400f;
    [SerializeField] private float maxBrakeTorque = 4200f;
    [SerializeField] private float maxSteerAngle = 32f;
    [SerializeField] private float steerSpeed = 6f;

    [Header(\"Mobil Fizik Kararlılığı\")]
    [SerializeField] private float truckMass = 8000f;
    [SerializeField] private Vector3 centerOfMassOffset = new Vector3(0f, -0.75f, 0.35f);
    [SerializeField] private float fixedTimestep = 0.016667f; // ~60 Hz

    [Header(\"Kabin Salınımı (Opsiyonel)\")]
    [SerializeField] private Transform cabinOrCameraRig;
    [SerializeField] private float pitchFromAccel = 2.2f;
    [SerializeField] private float rollFromTurn = 3.0f;
    [SerializeField] private float maxCabinAngle = 5.5f;
    [SerializeField] private float cabinStiffness = 8f;

    [Header(\"Dorse Bağlantısı (Opsiyonel)\")]
    [SerializeField] private Rigidbody trailerRigidbody;
    [SerializeField] private Transform fifthWheelAnchor;
    [SerializeField] private float trailerMass = 14000f;
    [SerializeField] private Vector3 trailerCenterOfMassOffset = new Vector3(0f, -0.65f, 0f);
    [Range(15f, 85f)]
    [SerializeField] private float maxTrailerYawAngle = 55f;
    [SerializeField] private float trailerYawSpring = 1500f;
    [SerializeField] private float trailerYawDamper = 450f;
    [SerializeField] private Collider[] truckColliders;
    [SerializeField] private Collider[] trailerColliders;

    private Rigidbody _rb;
    private float _currentSteerAngle;
    private float _throttleInput;
    private float _brakeInput;
    private bool _hasExternalHudInput;

    private Vector3 _lastVelocity;
    private Quaternion _initialCabinRot;
    private bool _hasCabinRig;

    private void Awake()
    {
        _rb = GetComponent<Rigidbody>();
        _rb.mass = Mathf.Max(100f, truckMass);
        _rb.interpolation = RigidbodyInterpolation.Interpolate;
        _rb.centerOfMass += centerOfMassOffset;

        if (fixedTimestep > 0.002f @COMMENT_BODY@@COMMENT_BODY@ fixedTimestep < 0.05f)
        {
            Time.fixedDeltaTime = fixedTimestep;
        }

        if (cabinOrCameraRig != null)
        {
            _initialCabinRot = cabinOrCameraRig.localRotation;
            _hasCabinRig = true;
        }

        _lastVelocity = GetRbVelocity(_rb);

        SetupTrailerIfAssigned();
    }

    public void SetControls(float throttle, float steer, float brake)
    {
        _hasExternalHudInput = true;
        _throttleInput = Mathf.Clamp(throttle, -1f, 1f);
        _brakeInput = Mathf.Clamp01(brake);

        float targetSteer = Mathf.Clamp(steer, -1f, 1f) * maxSteerAngle;
        _currentSteerAngle = Mathf.Lerp(
            _currentSteerAngle,
            targetSteer,
            Time.fixedDeltaTime * steerSpeed
        );
    }

    public void ClearExternalHudInput()
    {
        _hasExternalHudInput = false;
    }

    private void Update()
    {
        // Mobil UI bağlı değilse veya Editör'de klavye kullanılıyorsa fallback çalışır
        if (!_hasExternalHudInput)
        {
            float v = Input.GetAxisRaw(\"Vertical\");
            float h = Input.GetAxisRaw(\"Horizontal\");
            float b = Input.GetKey(KeyCode.Space) ? 1f : 0f;

            _throttleInput = Mathf.Clamp(v, -1f, 1f);
            _brakeInput = Mathf.Clamp01(b);

            float targetSteer = Mathf.Clamp(h, -1f, 1f) * maxSteerAngle;
            _currentSteerAngle = Mathf.Lerp(
                _currentSteerAngle,
                targetSteer,
                Time.deltaTime * steerSpeed
            );
        }
    }

    private void FixedUpdate()
    {
        ApplySteering();
        ApplyDriveAndBrake();
        UpdateCabinSuspension();
    }

    private void ApplySteering()
    {
        if (steerWheels == null) return;

        for (int i = 0; i < steerWheels.Length; i++)
        {
            if (steerWheels[i] != null)
            {
                steerWheels[i].steerAngle = _currentSteerAngle;
            }
        }
    }

    private void ApplyDriveAndBrake()
    {
        Vector3 vel = GetRbVelocity(_rb);
        float speedKmh = vel.magnitude * 3.6f;
        float speedFactor = Mathf.Clamp01(1f - (speedKmh / 110f));
        float motorTorque = _throttleInput * maxMotorTorque * (0.35f + 0.65f * speedFactor);
        float brakeTorque = _brakeInput * maxBrakeTorque;

        bool hasDriveWheels = false;
        if (driveWheels != null)
        {
            for (int i = 0; i < driveWheels.Length; i++)
            {
                if (driveWheels[i] != null)
                {
                    driveWheels[i].motorTorque = motorTorque;
                    hasDriveWheels = true;
                }
            }
        }

        if (allWheels != null)
        {
            for (int i = 0; i < allWheels.Length; i++)
            {
                if (allWheels[i] != null)
                {
                    allWheels[i].brakeTorque = brakeTorque;
                }
            }
        }

        // WheelCollider henüz bağlanmadıysa bile düz/dönüş testinin kırılmaması için güvenli fallback
        if (!hasDriveWheels)
        {
            Vector3 forwardForce = transform.forward * (_throttleInput * maxMotorTorque * 2.5f * speedFactor);
            _rb.AddForce(forwardForce, ForceMode.Force);

            if (vel.sqrMagnitude > 0.01f)
            {
                float turnDir = (_throttleInput >= -0.05f) ? 1f : -1f;
                float yawDelta = (_currentSteerAngle / Mathf.Max(1f, maxSteerAngle)) * 55f * turnDir * Time.fixedDeltaTime;
                _rb.MoveRotation(_rb.rotation * Quaternion.Euler(0f, yawDelta, 0f));
            }

            if (_brakeInput > 0.01f @COMMENT_BODY@@COMMENT_BODY@ vel.sqrMagnitude > 0.001f)
            {
                Vector3 brakeForce = -vel.normalized * (_brakeInput * maxBrakeTorque * 2.0f);
                _rb.AddForce(brakeForce, ForceMode.Force);
            }
        }
    }

    private void UpdateCabinSuspension()
    {
        if (!_hasCabinRig || cabinOrCameraRig == null) return;

        Vector3 currentVel = GetRbVelocity(_rb);
        float dt = Mathf.Max(0.0001f, Time.fixedDeltaTime);
        Vector3 accel = (currentVel - _lastVelocity) / dt;
        _lastVelocity = currentVel;

        Vector3 localAccel = transform.InverseTransformDirection(accel);

        float targetPitch = Mathf.Clamp(
            -localAccel.z * pitchFromAccel * 0.1f,
            -maxCabinAngle,
            maxCabinAngle
        );
        float targetRoll = Mathf.Clamp(
            -localAccel.x * rollFromTurn * 0.1f,
            -maxCabinAngle,
            maxCabinAngle
        );

        Quaternion targetRot = _initialCabinRot * Quaternion.Euler(targetPitch, 0f, targetRoll);
        cabinOrCameraRig.localRotation = Quaternion.Slerp(
            cabinOrCameraRig.localRotation,
            targetRot,
            Time.fixedDeltaTime * cabinStiffness
        );
    }

    private void SetupTrailerIfAssigned()
    {
        if (trailerRigidbody == null || fifthWheelAnchor == null) return;

        trailerRigidbody.mass = Mathf.Max(100f, trailerMass);
        trailerRigidbody.interpolation = RigidbodyInterpolation.Interpolate;
        trailerRigidbody.centerOfMass += trailerCenterOfMassOffset;
        trailerRigidbody.solverIterations = 12;
        trailerRigidbody.solverVelocityIterations = 6;

        if (truckColliders != null @COMMENT_BODY@@COMMENT_BODY@ trailerColliders != null)
        {
            for (int i = 0; i < truckColliders.Length; i++)
            {
                if (truckColliders[i] == null) continue;
                for (int j = 0; j < trailerColliders.Length; j++)
                {
                    if (trailerColliders[j] == null) continue;
                    Physics.IgnoreCollision(truckColliders[i], trailerColliders[j], true);
                }
            }
        }

        trailerRigidbody.transform.position = fifthWheelAnchor.position;
        trailerRigidbody.transform.rotation = fifthWheelAnchor.rotation;

        ConfigurableJoint joint = trailerRigidbody.GetComponent<ConfigurableJoint>();
        if (joint == null)
        {
            joint = trailerRigidbody.gameObject.AddComponent<ConfigurableJoint>();
        }

        joint.connectedBody = _rb;
        joint.autoConfigureConnectedAnchor = false;
        joint.anchor = Vector3.zero;
        joint.connectedAnchor = fifthWheelAnchor.localPosition;

        joint.xMotion = ConfigurableJointMotion.Locked;
        joint.yMotion = ConfigurableJointMotion.Locked;
        joint.zMotion = ConfigurableJointMotion.Locked;

        joint.angularXMotion = ConfigurableJointMotion.Limited;
        joint.angularYMotion = ConfigurableJointMotion.Limited;
        joint.angularZMotion = ConfigurableJointMotion.Limited;

        joint.angularYLimit = new SoftJointLimit
        {
            limit = maxTrailerYawAngle,
            bounciness = 0.05f,
            contactDistance = 2f
        };

        joint.lowAngularXLimit = new SoftJointLimit { limit = -2.5f };
        joint.highAngularXLimit = new SoftJointLimit { limit = 2.5f };
        joint.angularZLimit = new SoftJointLimit { limit = 1.25f };

        JointDrive drive = new JointDrive
        {
            positionSpring = trailerYawSpring,
            positionDamper = trailerYawDamper,
            maximumForce = Mathf.Infinity
        };
        joint.angularXDrive = drive;
        joint.angularYZDrive = drive;

        joint.projectionMode = JointProjectionMode.PositionAndRotation;
        joint.projectionDistance = 0.02f;
        joint.projectionAngle = 1f;
    }

    private static Vector3 GetRbVelocity(Rigidbody body)
    {
        if (body == null) return Vector3.zero;
#if UNITY_6000_0_OR_NEWER
        return body.linearVelocity;
#else
        return body.velocity;
#endif
    }
}

// ============================================================================
// 2. BASILI TUTMA BUTONU (MOBİL GAZ / GERİ / FREN)
// ============================================================================
[DisallowMultipleComponent]
public class TruckHoldButton : MonoBehaviour, IPointerDownHandler, IPointerUpHandler, IPointerExitHandler
{
    public bool IsHeld { get; private set; }

    public void OnPointerDown(PointerEventData eventData) => IsHeld = true;
    public void OnPointerUp(PointerEventData eventData) => IsHeld = false;
    public void OnPointerExit(PointerEventData eventData) => IsHeld = false;
    private void OnDisable() => IsHeld = false;
}

// ============================================================================
// 3. MOBİL DOKUNMATİK HUD KONTROLCÜSÜ
// ============================================================================
[DisallowMultipleComponent]
public class MobileTruckHudBridge : MonoBehaviour
{
    [SerializeField] private MobileTruckCompleteSystem truckSystem;
    [SerializeField] private Slider steerSlider;
    [SerializeField] private TruckHoldButton gasButton;
    [SerializeField] private TruckHoldButton reverseButton;
    [SerializeField] private TruckHoldButton brakeButton;
    [SerializeField] private float returnToCenterSpeed = 7f;
    [SerializeField] private bool autoCenterWhenReleased = true;

    private bool _isDraggingSteer;
    private float _currentSteer;

    private void OnEnable()
    {
        if (steerSlider != null)
        {
            steerSlider.minValue = -1f;
            steerSlider.maxValue = 1f;
            steerSlider.onValueChanged.AddListener(OnSteerChanged);
        }
    }

    private void OnDisable()
    {
        if (steerSlider != null)
        {
            steerSlider.onValueChanged.RemoveListener(OnSteerChanged);
        }

        if (truckSystem != null)
        {
            truckSystem.ClearExternalHudInput();
        }
    }

    private void Update()
    {
        if (autoCenterWhenReleased @COMMENT_BODY@@COMMENT_BODY@ !_isDraggingSteer @COMMENT_BODY@@COMMENT_BODY@ steerSlider != null)
        {
            if (!Mathf.Approximately(steerSlider.value, 0f))
            {
                float next = Mathf.MoveTowards(steerSlider.value, 0f, returnToCenterSpeed * Time.deltaTime);
                steerSlider.SetValueWithoutNotify(next);
                _currentSteer = next;
            }
        }
    }

    private void FixedUpdate()
    {
        if (truckSystem == null) return;

        bool gas = gasButton != null @COMMENT_BODY@@COMMENT_BODY@ gasButton.IsHeld;
        bool rev = reverseButton != null @COMMENT_BODY@@COMMENT_BODY@ reverseButton.IsHeld;
        bool brk = brakeButton != null @COMMENT_BODY@@COMMENT_BODY@ brakeButton.IsHeld;

        float throttle = 0f;
        if (gas @COMMENT_BODY@@COMMENT_BODY@ !rev) throttle = 1f;
        else if (rev @COMMENT_BODY@@COMMENT_BODY@ !gas) throttle = -1f;

        float brake = brk ? 1f : 0f;
        truckSystem.SetControls(throttle, _currentSteer, brake);
    }

    private void OnSteerChanged(float val)
    {
        _currentSteer = Mathf.Clamp(val, -1f, 1f);
    }

    public void SetSteerDragging(bool dragging) => _isDraggingSteer = dragging;
}

// ============================================================================
// 4. 60 FPS DOSTU AYNA KAMERASI
// ============================================================================
[DisallowMultipleComponent]
[RequireComponent(typeof(Camera))]
public class MobileMirrorRenderer : MonoBehaviour
{
    [Min(1)]
    [SerializeField] private int renderInterval = 3;
    [SerializeField] private RenderTexture mirrorTexture;

    private Camera _cam;
    private int _counter;

    private void Awake()
    {
        _cam = GetComponent<Camera>();
        if (mirrorTexture != null)
        {
            _cam.targetTexture = mirrorTexture;
        }
        _cam.enabled = false;
    }

    private void LateUpdate()
    {
        if (mirrorTexture == null || _cam == null) return;

        _counter++;
        if (_counter >= renderInterval)
        {
            _counter = 0;
            _cam.Render();
        }
    }
}

